definition.script:
pipeline {
  agent none

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '20'))
    timeout(time: 330, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  stages {
    stage('Base Images') {
      steps {
        // propagate:false -- a disk-gated/UNSTABLE base must not block apps;
        // the apps job pulls the last-good base from Nexus regardless.
        build job: 'businessplanner-base-images', wait: true, propagate: false
      }
    }

    stage('Service Images') {
      steps {
        build job: 'businessplanner-apps', wait: true, propagate: true
      }
    }
  }
}
